import React, { useState, useEffect } from "react";

import {
  addIncome,
  updateIncome,
} from "../../api/incomeApi";

import {
  addExpense,
  updateExpense,
} from "../../api/expenseApi";

const AddTransaction = ({
  onTransactionAdded,
  editingTransaction,
  setEditingTransaction,
}) => {

  const [transaction, setTransaction] = useState({
    title: "",
    amount: "",
    category: "",
    type: "",
    date: "",
    paymentMethod: "",
    notes: "",
  });

  useEffect(() => {
    if (editingTransaction) {
      setTransaction({
        title: editingTransaction.title || "",
        amount: editingTransaction.amount || "",
        category: editingTransaction.category || "",
        type: editingTransaction.type || "",
        date: editingTransaction.date
          ? editingTransaction.date.substring(0, 10)
          : "",
        paymentMethod:
          editingTransaction.payment || "",
        notes:
          editingTransaction.notes || "",
      });
    }
  }, [editingTransaction]);

  const handleChange = (e) => {
    setTransaction({
      ...transaction,
      [e.target.name]: e.target.value,
    });
  };
  const handleSubmit = async (e) => {
  e.preventDefault();

  try {

    // ==========================
    // UPDATE TRANSACTION
    // ==========================
    if (editingTransaction) {

      if (transaction.type === "Income") {

        await updateIncome(editingTransaction._id, {
          title: transaction.title,
          amount: Number(transaction.amount),
          category: transaction.category,
          date: transaction.date,
          paymentMethod: transaction.paymentMethod,
          notes: transaction.notes,
        });

      } else {

        await updateExpense(editingTransaction._id, {
          name: transaction.title,
          amount: Number(transaction.amount),
          category: transaction.category,
          date: transaction.date,
          paymentMethod: transaction.paymentMethod,
          notes: transaction.notes,
        });

      }

      alert("Transaction Updated Successfully!");
      setEditingTransaction(null);

    }

    // ==========================
    // ADD NEW TRANSACTION
    // ==========================
    else {

      if (transaction.type === "Income") {

        await addIncome({
          title: transaction.title,
          amount: Number(transaction.amount),
          category: transaction.category,
          date: transaction.date,
          paymentMethod: transaction.paymentMethod,
          notes: transaction.notes,
        });

      } else {

        await addExpense({
          name: transaction.title,
          amount: Number(transaction.amount),
          category: transaction.category,
          date: transaction.date,
          paymentMethod: transaction.paymentMethod,
          notes: transaction.notes,
        });

      }

      alert("Transaction Added Successfully!");
    }

    // Refresh Transaction Table
    if (onTransactionAdded) {
      onTransactionAdded();
    }

    // Reset Form
    setTransaction({
      title: "",
      amount: "",
      category: "",
      type: "",
      date: "",
      paymentMethod: "",
      notes: "",
    });

   } catch (error) {

  console.error("Full Error:", error);

  if (error.response) {

    console.log("Status:", error.response.status);
    console.log("Data:", error.response.data);

    alert(
      `Error ${error.response.status}: ${
        error.response.data.message || "Unknown error"
      }`
    );

  } else {

    alert(error.message);

  }

}
  return(
    <div className="bg-slate-800 rounded-2xl p-6 shadow-lg">

      <h2 className="text-2xl font-bold text-white mb-6">
        {editingTransaction
          ? "Update Transaction"
          : "Add New Transaction"}
      </h2>

      <form
        onSubmit={handleSubmit}
        className="grid grid-cols-1 md:grid-cols-2 gap-4"
      >

        {/* Title */}
        <input
          type="text"
          name="title"
          placeholder="Transaction Title"
          value={transaction.title}
          onChange={handleChange}
          className="p-3 rounded-lg bg-slate-700 text-white outline-none focus:ring-2 focus:ring-violet-500"
          required
        />

        {/* Amount */}
        <input
          type="number"
          name="amount"
          placeholder="Amount"
          value={transaction.amount}
          onChange={handleChange}
          className="p-3 rounded-lg bg-slate-700 text-white outline-none focus:ring-2 focus:ring-violet-500"
          required
        />

        {/* Transaction Type */}
        <select
          name="type"
          value={transaction.type}
          onChange={handleChange}
          className="p-3 rounded-lg bg-slate-700 text-white"
          required
        >
          <option value="">Select Transaction Type</option>
          <option value="Income">Income</option>
          <option value="Expense">Expense</option>
        </select>

        {/* Category */}
        <select
          name="category"
          value={transaction.category}
          onChange={handleChange}
          className="p-3 rounded-lg bg-slate-700 text-white"
          required
        >
          <option value="">Select Category</option>

          {transaction.type === "Income" ? (
            <>
              <option value="Salary">Salary</option>
              <option value="Freelancing">Freelancing</option>
              <option value="Business">Business</option>
              <option value="Investment">Investment</option>
              <option value="Other Income">Other Income</option>
            </>
          ) : (
            <>
              <option value="Food">Food</option>
              <option value="Travel">Travel</option>
              <option value="Shopping">Shopping</option>
              <option value="Bills">Bills</option>
              <option value="Medical">Medical</option>
              <option value="Entertainment">Entertainment</option>
              <option value="Education">Education</option>
              <option value="Other">Other</option>
            </>
          )}
        </select>

        {/* Date */}
        <input
          type="date"
          name="date"
          value={transaction.date}
          onChange={handleChange}
          className="p-3 rounded-lg bg-slate-700 text-white"
          required
        />

        {/* Payment Method */}
        <select
          name="paymentMethod"
          value={transaction.paymentMethod}
          onChange={handleChange}
          className="p-3 rounded-lg bg-slate-700 text-white"
          required
        >
          <option value="">Payment Method</option>
          <option value="Cash">Cash</option>
          <option value="UPI">UPI</option>
          <option value="Credit Card">Credit Card</option>
          <option value="Debit Card">Debit Card</option>
          <option value="Net Banking">Net Banking</option>
        </select>
                {/* Notes */}
        <textarea
          name="notes"
          placeholder="Notes"
          value={transaction.notes}
          onChange={handleChange}
          rows="3"
          className="md:col-span-2 p-3 rounded-lg bg-slate-700 text-white outline-none focus:ring-2 focus:ring-violet-500"
        />

        {/* Buttons */}
        <div className="md:col-span-2 flex gap-4 mt-4">

          <button
            type="submit"
            className="flex-1 bg-gradient-to-r from-violet-600 via-fuchsia-600 to-blue-600 hover:opacity-90 text-white py-3 rounded-xl font-semibold transition"
          >
            {editingTransaction
              ? "Update Transaction"
              : "Add Transaction"}
          </button>

          {editingTransaction && (
            <button
              type="button"
              onClick={() => {
                setEditingTransaction(null);

                setTransaction({
                  title: "",
                  amount: "",
                  category: "",
                  type: "",
                  date: "",
                  paymentMethod: "",
                  notes: "",
                });
              }}
              className="px-8 bg-red-600 hover:bg-red-700 text-white rounded-xl font-semibold transition"
            >
              Cancel
            </button>
          )}

        </div>

      </form>

    </div>
  );
};
};
export default AddTransaction;